#define APPS 2048
#define THREADS 8192
#define LEDGERS 4096
#define RULES 256
typedef unsigned long long U64;
typedef struct {unsigned uid; U64 version; char package[161],apk[512];} App;
typedef struct {int pid,tid,app,mask,samples;unsigned uid;U64 start,last,total;double stamp,peak;char name[65],process[161];} Entry;
typedef struct {int pid,tid,original,applied,requested,seen,blocked;U64 start;} Lease;
typedef struct {char package[161],pattern[65];U64 version;int mask;} Rule;
static App apps[APPS];static int napps;static char base[256];static volatile sig_atomic_t stopped;
static Lease leases[LEDGERS];static int nleases;static Rule rules[RULES];static int nrules;
static int recordIndex[THREADS*2],lastCpu;
static double clocknow(void){struct timespec t;clock_gettime(CLOCK_BOOTTIME,&t);return t.tv_sec+t.tv_nsec/1e9;}
static void onstop(int s){(void)s;stopped=1;}
static void path(char *out,size_t size,const char *name){snprintf(out,size,"%s/%s",base,name);}
static int readtext(const char *file,char *out,size_t size){FILE *f=fopen(file,"r");if(!f)return 0;size_t n=fread(out,1,size-1,f);out[n]=0;fclose(f);return n>0;}
static void safe(char *s){for(;*s;s++)if((unsigned char)*s<32||*s==127)*s=' ';}
static void status(const char *phase,int elapsed,int count,int capped){char file[512],temp[512];path(file,sizeof file,"record.state");path(temp,sizeof temp,"record.state.tmp");FILE *f=fopen(temp,"w");if(f){fprintf(f,"%s\t%d\t%d\t%d\n",phase,elapsed,count,capped);fclose(f);rename(temp,file);}}
static void rootgroup(void){const char *files[]={"/sys/fs/cgroup/cgroup.procs","/dev/cpuset/tasks"};for(int i=0;i<2;i++){FILE *f=fopen(files[i],"w");if(f){fprintf(f,"%d\n",getpid());fclose(f);}}}
static void pidfile(const char *name){char file[512];path(file,sizeof file,name);FILE *f=fopen(file,"w");if(f){fprintf(f,"%d\n",getpid());fclose(f);}}
static void loadapps(void){char file[512],line[1024];path(file,sizeof file,"packages.tsv");FILE *f=fopen(file,"r");napps=0;if(!f)return;while(napps<APPS&&fgets(line,sizeof line,f)){App a;if(sscanf(line,"%u\t%llu\t%160s\t%511s",&a.uid,&a.version,a.package,a.apk)==4)apps[napps++]=a;}fclose(f);}
static int identify(int pid,char *process,size_t size,unsigned *actual){process[0]=0;*actual=0;char file[128],data[512];snprintf(file,sizeof file,"/proc/%d/cmdline",pid);if(!readtext(file,process,size))return -1;safe(process);unsigned uid=0;snprintf(file,sizeof file,"/proc/%d/status",pid);FILE *f=fopen(file,"r");if(!f)return -1;while(fgets(data,sizeof data,f))if(sscanf(data,"Uid:\t%u",&uid)==1)break;fclose(f);*actual=uid;int only=-1,count=0;for(int i=0;i<napps;i++){if(apps[i].uid!=uid||access(apps[i].apk,F_OK)!=0)continue;size_t len=strlen(apps[i].package);if(apps[i].uid==uid&&!strncmp(process,apps[i].package,len)&&(process[len]==0||process[len]==':'))return i;if(apps[i].uid==uid){only=i;count++;}}return count==1?only:-1;}
static int threadstat(int pid,int tid,U64 *start,U64 *ticks,char *name){char file[128],data[4096];snprintf(file,sizeof file,"/proc/%d/task/%d/stat",pid,tid);if(!readtext(file,data,sizeof data))return 0;char *left=strchr(data,'('),*right=strrchr(data,')');if(!left||!right||right<=left)return 0;size_t len=right-left-1;if(len>64)len=64;memcpy(name,left+1,len);name[len]=0;safe(name);char *state=NULL,*token=strtok_r(right+2," ",&state);int field=3;U64 user=0,kernel=0;*start=0;lastCpu=-1;while(token){if(field==14)user=strtoull(token,NULL,10);if(field==15)kernel=strtoull(token,NULL,10);if(field==22)*start=strtoull(token,NULL,10);if(field==39)lastCpu=atoi(token);field++;token=strtok_r(NULL," ",&state);}*ticks=user+kernel;return *start>0;}
static int affinity(int tid){cpu_set_t set;CPU_ZERO(&set);if(sched_getaffinity(tid,sizeof set,&set))return 0;int mask=0;for(int i=0;i<8;i++)if(CPU_ISSET(i,&set))mask|=1<<i;return mask;}
static int setaffinity(int tid,int mask){cpu_set_t set;CPU_ZERO(&set);for(int i=0;i<8;i++)if(mask&(1<<i))CPU_SET(i,&set);return sched_setaffinity(tid,sizeof set,&set)==0;}
static void loadleases(void){char file[512],line[256],current[64];path(file,sizeof file,"threads.lease");FILE *f=fopen(file,"r");nleases=0;if(!f)return;readtext("/proc/sys/kernel/random/boot_id",current,sizeof current);if(!fgets(line,sizeof line,f)||strcmp(line,current)){fclose(f);return;}while(nleases<LEDGERS&&fgets(line,sizeof line,f)){Lease l={0};if(sscanf(line,"%d %d %llu %d %d %d %d",&l.pid,&l.tid,&l.start,&l.original,&l.applied,&l.requested,&l.blocked)==7)leases[nleases++]=l;}fclose(f);}
static int saveleases(void){char file[512],temp[512],boot[64];path(file,sizeof file,"threads.lease");path(temp,sizeof temp,"threads.lease.tmp");readtext("/proc/sys/kernel/random/boot_id",boot,sizeof boot);FILE *f=fopen(temp,"w");if(!f)return 0;fputs(boot,f);for(int i=0;i<nleases;i++){Lease *l=&leases[i];fprintf(f,"%d %d %llu %d %d %d %d\n",l->pid,l->tid,l->start,l->original,l->applied,l->requested,l->blocked);}int success=!ferror(f);fclose(f);return success&&rename(temp,file)==0;}
static void restore(Lease *l){U64 start,ticks;char name[65];if(threadstat(l->pid,l->tid,&start,&ticks,name)&&start==l->start&&affinity(l->tid)==l->applied)setaffinity(l->tid,l->original);}
static void loadrules(void){char file[512],line[512];path(file,sizeof file,"threads.rules");FILE *f=fopen(file,"r");nrules=0;if(!f)return;while(nrules<RULES&&fgets(line,sizeof line,f)){Rule r;if(sscanf(line,"%160[^\t]\t%llu\t%64[^\t]\t%d",r.package,&r.version,r.pattern,&r.mask)==4&&r.mask>0&&r.mask<=255)rules[nrules++]=r;}fclose(f);}
static int threadmask(int app,int pid,int tid,const char *name,int floating){for(int i=0;i<nrules;i++)if(!strcmp(rules[i].package,apps[app].package)&&rules[i].version==apps[app].version&&fnmatch(rules[i].pattern,name,0)==0){int m=rules[i].mask;if(floating&&(pid==tid||!strcmp(name,"RenderThread")))m|=240;return m;}return 0;}
static int watchthreads(void){char lockfile[512],enabled[512],mode[512],data[32];path(lockfile,sizeof lockfile,"threads.lock");int fd=open(lockfile,O_CREAT|O_RDWR,0600);if(fd<0||flock(fd,LOCK_EX|LOCK_NB))return 2;path(enabled,sizeof enabled,"persistent-enabled");path(mode,sizeof mode,"window_mode");pidfile("threads.pid");loadleases();loadapps();while(!stopped&&access(enabled,F_OK)==0){loadapps();loadrules();if(!nrules)break;for(int i=0;i<nleases;i++)leases[i].seen=0;int floating=readtext(mode,data,sizeof data)&&!strncmp(data,"floating",8);DIR *proc=opendir("/proc");struct dirent *p;int changed=0;if(proc){while((p=readdir(proc))){int pid=atoi(p->d_name);if(pid<=0)continue;char process[161]={0};unsigned uid=0;int app=identify(pid,process,sizeof process,&uid);if(app<0)continue;int wanted=0;for(int r=0;r<nrules;r++)if(!strcmp(rules[r].package,apps[app].package)&&rules[r].version==apps[app].version){wanted=1;break;}if(!wanted)continue;char dir[128];snprintf(dir,sizeof dir,"/proc/%d/task",pid);DIR *tasks=opendir(dir);if(!tasks)continue;struct dirent *t;while((t=readdir(tasks))){int tid=atoi(t->d_name);U64 start,ticks;char name[65];if(tid<=0||!threadstat(pid,tid,&start,&ticks,name))continue;int mask=threadmask(app,pid,tid,name,floating);if(!mask)continue;int isnew=0,index=-1;for(int i=0;i<nleases;i++)if(leases[i].pid==pid&&leases[i].tid==tid&&leases[i].start==start){index=i;break;}int current=affinity(tid);if(!current)continue;if(index<0){if(nleases>=LEDGERS)continue;index=nleases++;isnew=1;leases[index]=(Lease){.pid=pid,.tid=tid,.start=start,.original=current,.applied=current,.requested=mask};changed=1;}Lease *l=&leases[index];l->seen=1;int requestChanged=isnew||l->requested!=mask;if(l->requested!=mask){l->requested=mask;l->blocked=0;changed=1;}else if(current!=l->applied&&!l->blocked){l->blocked=1;changed=1;}if(l->blocked||current==mask||(!requestChanged&&current==l->applied))continue;
                /* Persist identity and original affinity before changing a live task. */
                l->applied=mask;if(!saveleases()){l->applied=current;continue;}U64 verified,again;if(threadstat(pid,tid,&verified,&again,name)&&verified==start&&setaffinity(tid,mask)){l->applied=affinity(tid);changed=1;}else{l->applied=current;changed=1;}
            }closedir(tasks);}}if(proc)closedir(proc);for(int i=nleases-1;i>=0;i--)if(!leases[i].seen){restore(&leases[i]);leases[i]=leases[--nleases];changed=1;}if(changed)saveleases();for(int i=0;i<30&&!stopped;i++)usleep(100000);}
    for(int i=0;i<nleases;i++)restore(&leases[i]);nleases=0;saveleases();close(fd);return 0;}
static long numeric(const char *file){char data[512];if(!readtext(file,data,sizeof data))return -1;char *s=data;long found=-1;while(*s){char *end;long n=strtol(s,&end,10);if(end!=s){if(n>=100000&&n<=5000000)found=n;s=end;}else s++;}return found;}
static long gpucurrent(void){long freq=numeric("/sys/kernel/ged/hal/current_freqency");if(freq>=338000&&freq<=1612000)return freq;return -1;}
static void summary(Entry *entries,int count,double duration){char file[512],temp[512];path(file,sizeof file,"record.threads.tsv");path(temp,sizeof temp,"record.threads.tmp");FILE *f=fopen(temp,"w");if(!f)return;long hz=sysconf(_SC_CLK_TCK);fprintf(f,"#durationMs=%.0f\n",duration*1000);fprintf(f,"package\tversion\tprocess\tuid\tpid\ttid\tstart\tname\taverage\tpeak\tmask\tsamples\n");for(int i=0;i<count;i++){Entry *e=&entries[i];App unknown={.version=0,.package="unassigned"};App *a=e->app>=0?&apps[e->app]:&unknown;fprintf(f,"%s\t%llu\t%s\t%u\t%d\t%d\t%llu\t%s\t%.4f\t%.4f\t%d\t%d\n",a->package,a->version,e->process,e->uid,e->pid,e->tid,e->start,e->name,100.0*e->total/hz/(duration>0?duration:1),e->peak,e->mask,e->samples);}fclose(f);rename(temp,file);}
#include "frames.h"
#include "metrics.h"
static int record(int seconds,const char *selection){if(seconds<5||seconds>600)return 2;char file[512];path(file,sizeof file,"record.lock");int lockfd=open(file,O_CREAT|O_RDWR|O_CLOEXEC,0600);if(lockfd<0||flock(lockfd,LOCK_EX|LOCK_NB))return 2;loadapps();if(!napps)return 3;Entry *entries=calloc(THREADS,sizeof *entries);if(!entries)return 4;path(file,sizeof file,"record.frequencies.csv");FILE *freq=fopen(file,"w");if(!freq){free(entries);return 5;}fputs("elapsedMs,cpu0KHz,cpu4KHz,cpu7KHz,gpuKHz\n",freq);path(file,sizeof file,"record.timeline.csv");FILE *timeline=fopen(file,"w");if(!timeline){fclose(freq);free(entries);return 5;}fputs("elapsedMs,pid,tid,startTicks,cpuPercent,intervalMs,lastCpu\n",timeline);int rows=0;path(file,sizeof file,"record.metrics.csv");FILE *measurement=fopen(file,"w");if(!measurement){fclose(timeline);fclose(freq);free(entries);return 5;}fputs("elapsedMs,currentUa,voltageUv,batteryDeciC,charging,gpuUtilPercent\n",measurement);pidfile("record.pid");framestart(seconds,selection);double began=frames.began/1e9,next=began;int count=0,capped=0;long hz=sysconf(_SC_CLK_TCK);while(!stopped){double now=clocknow(),elapsed=now-began;if(elapsed>=seconds)break;fprintf(freq,"%.0f,%ld,%ld,%ld,%ld\n",elapsed*1000,numeric("/sys/devices/system/cpu/cpufreq/policy0/scaling_cur_freq"),numeric("/sys/devices/system/cpu/cpufreq/policy4/scaling_cur_freq"),numeric("/sys/devices/system/cpu/cpufreq/policy7/scaling_cur_freq"),gpucurrent());fflush(freq);DIR *proc=opendir("/proc");struct dirent *p;if(proc){while((p=readdir(proc))){int pid=atoi(p->d_name);if(pid<=0)continue;char process[161]={0};unsigned uid=0;int app=identify(pid,process,sizeof process,&uid);if(!process[0]||(strcmp(selection,"*")&&(app<0||strcmp(selection,apps[app].package))))continue;char dir[128];snprintf(dir,sizeof dir,"/proc/%d/task",pid);DIR *tasks=opendir(dir);if(!tasks)continue;struct dirent *t;while((t=readdir(tasks))){int tid=atoi(t->d_name);U64 start,ticks;char name[65];if(tid<=0||!threadstat(pid,tid,&start,&ticks,name))continue;if(pid==tid)framepid(pid,app,start);unsigned slot=(unsigned)((start^(start>>32)^(U64)pid*2654435761U^(U64)tid*2246822519U)&(THREADS*2-1));int index=-1;while(recordIndex[slot]){int existing=recordIndex[slot]-1;if(entries[existing].pid==pid&&entries[existing].tid==tid&&entries[existing].start==start){index=existing;break;}slot=(slot+1)&(THREADS*2-1);}if(index<0){if(count>=THREADS){capped=1;continue;}index=count++;recordIndex[slot]=index+1;entries[index]=(Entry){.pid=pid,.tid=tid,.app=app,.uid=uid,.start=start,.last=ticks,.stamp=now};snprintf(entries[index].name,sizeof entries[index].name,"%s",name);snprintf(entries[index].process,sizeof entries[index].process,"%s",process);}Entry *e=&entries[index];double gap=now-e->stamp;if(gap>0.001&&ticks>=e->last){U64 delta=ticks-e->last;double use=100.0*delta/hz/gap;if(delta&&rows<200000){fprintf(timeline,"%.0f,%d,%d,%llu,%.4f,%.0f,%d\n",elapsed*1000,pid,tid,start,use>100?100:use,gap*1000,lastCpu);rows++;if(rows==200000){path(file,sizeof file,"record.timeline-capped");FILE *cap=fopen(file,"w");if(cap){fputs("1\n",cap);fclose(cap);}}}e->total+=delta;if(use>e->peak)e->peak=use>100?100:use;}e->last=ticks;e->stamp=now;e->mask=affinity(tid);e->samples++;}closedir(tasks);}}if(proc)closedir(proc);metrics(measurement,elapsed);frameupdate();live(elapsed);fflush(timeline);status("recording",(int)(elapsed*1000),count,capped);if((int)elapsed%10==0)summary(entries,count,elapsed);next+=1;double wait=next-clocknow();if(wait>0)usleep((useconds_t)(wait*1000000));else next=clocknow();}
    double elapsed=clocknow()-began;status("processing",(int)(elapsed*1000),count,capped);framefinish();summary(entries,count,elapsed);status(stopped?"stopped":"complete",(int)(elapsed*1000),count,capped);fclose(measurement);fclose(timeline);fclose(freq);free(entries);close(lockfd);return 0;}
int main(int argc,char **argv){umask(0077);if(argc<3||geteuid()!=0)return 1;snprintf(base,sizeof base,"%s",argv[2]);rootgroup();nice(10);signal(SIGTERM,onstop);signal(SIGINT,onstop);if(!strcmp(argv[1],"threads"))return watchthreads();if(!strcmp(argv[1],"restore-threads")){loadleases();for(int i=0;i<nleases;i++)restore(&leases[i]);nleases=0;saveleases();return 0;}if(!strcmp(argv[1],"record")&&argc==5)return record(atoi(argv[3]),argv[4]);return 2;}
